script:
frappe.ui.form.on('School House', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Student",
                    filters: { "custom_falemohe": frm.doc.name },
                    fields: ["name", "first_name", "last_name"]
                },
                callback: function(r) {
                    if (r.message) {
                        frm.clear_table("custom_students"); // Use your actual table field name
                        r.message.forEach(stu => {
                            let child = frm.add_child("custom_students");
                            child.student = stu.name;
                            child.student_name = stu.first_name + " " + (stu.last_name || "");
                        });
                        frm.refresh_field("custom_students");
                    }
                }
            });
        }
    }
});
